alternative.example:
type Todo = { id: i32, title: String, done: bool }      // 構造的: 同じ形の無名の値と互換
@nominal type Meters = { v: f64 }                       // 名前で区別: { v: f64 } や Celsius とは別の型
@nominal type Celsius = { v: f64 }

fn toggle(t: Todo) -> Todo { { ...t, done: !t.done } }  // OK: 結果の型は Todo のまま
fn bad(t: Todo) -> Todo { { ...t, done: 1 } }
// error: `done` is bool in Todo; a spread update keeps the type of `...t`

